                "inference_estimated_ram_mib_per_job": 1.0,
            },
        }
        results = campaign_cli._run_adaptive_inference_tasks(
            tasks,
            cfg=cfg,
            phase="evaluation",
            device="cuda:0",
            progress=Progress(),
        )
